      const frames = mockFramesRef.current.length > 0 ? mockFramesRef.current : undefined
      const res = await apiCall<{ success: boolean; feedback: SessionFeedback }>(`/interviews/mock/${mockSession.id}/end`, {
        method: 'POST',
